-- MERRY database objects (rendered from settings.py by deploy.py). Semantic view (replaceable).
-- @owner ADMIN runs as ACCOUNTADMIN, @owner APP as {{ROLE}} (no secondary roles).

-- @owner APP
create or replace semantic view {{DB}}.AGENT.AUDIT_SV
	tables (
		{{DB}}.CONTRACT.CONTRACTORS primary key (CONTRACTOR_CODE) with synonyms=('vendor','supplier','service company') comment='Contractors under each service contract, with contract term start and end dates.',
		{{DB}}.CONTRACT.CONTRACTS primary key (CONTRACT_ID) comment='Service contracts (master service agreements).',
		{{DB}}.CONTRACT.RATES primary key (CONTRACT_ID,RATE_CODE) comment='Contract rate schedule (Exhibit A). Standby rate applies to equipment idle on location.',
		{{DB}}.CONTRACT.RULE_PARAMS primary key (CONTRACT_ID,PARAM) comment='Audit rule parameters extracted from contract clauses (standby percentage, travel cap, excluded charges).',
		{{DB}}.CONTRACT.CLAUSES primary key (CONTRACT_ID,CLAUSE_NO) comment='Contract clause text. Use the CONTRACT_SEARCH tool for clause meaning; this table is for listing clauses.',
		{{DB}}.RAW.DAILY_REPORTS primary key (REPORT_DATE) comment='One site daily report per date with weather, operations status and camp headcount.',
		{{DB}}.RAW.GATE_LOG primary key (GATE_ENTRY_ID) with synonyms=('gate records','site access log','gate entries') comment='Site gate entries. Each row is one entry (a trip for equipment/vehicles, a visit for a person) with time in and time out. On-site hours = time out minus time in.',
		{{DB}}.RAW.EQUIPMENT_LOG primary key (LOG_DATE,EQUIPMENT_ID) comment='Daily equipment status per unit as recorded by the site.',
		{{DB}}.RAW.TIMESHEETS primary key (WORK_DATE,WORKER_ID) with synonyms=('time sheets','labour records') comment='Approved worker timesheets, one row per worker per day.',
		EQUIPMENT as {{DB}}.CURATED.V_EQUIPMENT primary key (EQUIPMENT_ID) comment='Equipment units seen in the equipment log or at the gate.',
		WORKERS as {{DB}}.CURATED.V_WORKERS primary key (WORKER_ID) with synonyms=('personnel','crew','staff') comment='Contractor personnel (crew) seen on timesheets or at the gate.',
		WORKER_DAY_HOURS as {{DB}}.CURATED.V_WORKER_DAY_HOURS primary key (WORKER_ID,WORK_DATE) comment='Per worker per day, gate (on-site) hours next to timesheet hours. hours_over_gate > 0 means more time billed than spent on site.',
		INVOICES as {{DB}}.CURATED.INVOICE_HEADERS primary key (INVOICE_NO) comment='Curated contractor invoice headers. Subtotal is before 12% VAT.',
		{{DB}}.CURATED.INVOICE_LINES primary key (INVOICE_NO,LINE_NO) comment='Invoice line items (before VAT).',
		{{DB}}.CURATED.INVOICE_LINE_DAYS primary key (INVOICE_NO,LINE_NO,SERVICE_DATE) comment='Each service day covered by an invoice line (from the line dates or its field tickets).',
		{{DB}}.CURATED.TICKETS primary key (TICKET_NO) with synonyms=('field tickets','work tickets') comment='Field tickets (daily work tickets) with signature status.',
		{{DB}}.CURATED.TICKET_ITEMS comment='Items on field tickets (personnel hours or equipment).',
		EXCEPTIONS as {{DB}}.AUDIT.V_EXCEPTIONS primary key (EXCEPTION_ID) with synonyms=('flags','findings','exceptions','candidate errors') comment='Candidate billing errors flagged by the SQL rule checks, one per invoice line group. evidence_summary is a readable version of the evidence. Use rule_type to group (e.g. SITE_EQUIPMENT_DAYS, RATE, DUPLICATE).',
		DECISIONS as {{DB}}.AUDIT.V_DECISIONS primary key (EXCEPTION_ID,VERSION) comment='Agent/analyst decisions on exceptions, one row per version. decision is CONFIRM (flag stands in full), CORRECT (part of the charge is payable, the rest is overbilled), WITHHOLD (payment held pending documents) or DISMISS (flag cleared). Use only current rows (is_current = TRUE). A decision is upheld when upheld_php > 0 (is_upheld = TRUE): CONFIRM, CORRECT and WITHHOLD can all be upheld; upheld_php = overbilled_php + withheld_php.',
		ACTIVITY as {{DB}}.APP.V_ACTIVITY with synonyms=('history','audit trail','log','who changed','did anyone override','what did we decide','changes','overrides') comment='Step 12d (D28) history: who did what and when on a contract, one row per event. kind is UPLOAD (files dropped), CONTRACT_CONFIRMED, AGENT_DECISION (MERRY''s review of a flag), OVERRIDE (an analyst changed MERRY''s decision; summary includes the reason), APPROVAL (an invoice''s resolution approved), CONTRACT_EDIT (a contract value changed) or CHAT_ACTION (an action confirmed in chat). subject is the invoice number for decisions, overrides and approvals. summary is a plain sentence with the amounts. For "what did we decide" on an invoice, return its AGENT_DECISION, OVERRIDE and APPROVAL rows in time order; "did anyone change it" means any OVERRIDE rows.',
		UI_FLAGS as {{DB}}.APP.V_UI_FLAGS primary key (FLAG_ID) with synonyms=('issues','issue list','findings status','flag status','dashboard issues') comment='D32: the root app Issues tab and Dashboard, one row per finding (same rows as EXCEPTIONS, current decision). status is OPEN (drafted, not settled), CONFIRMED (upheld and settled or approved), DISMISSED (cleared), or RECOVERED (credit note recorded). impact_php is the upheld (not payable) amount. Use this table for status reports and for any count or total the screens show.',
		UI_KPIS as {{DB}}.APP.V_UI_KPIS_BY_CONTRACT primary key (CONTRACT_ID) with synonyms=('dashboard','status report','kpis','totals','summary') comment='D32: the Dashboard numbers, one row per contract: invoices (approved, waiting, with findings), documents reviewed, spend reviewed (total due incl. VAT), findings by status, upheld, potential (open), confirmed and recovered pesos. A status report lists these per contract.'
	)
	relationships (
		RATES_TO_CONTRACTOR as RATES(CONTRACTOR_CODE) references CONTRACTORS(CONTRACTOR_CODE),
		PARAMS_TO_CONTRACT as RULE_PARAMS(CONTRACT_ID) references CONTRACTS(CONTRACT_ID),
		CLAUSES_TO_CONTRACT as CLAUSES(CONTRACT_ID) references CONTRACTS(CONTRACT_ID),
		GATE_TO_CONTRACTOR as GATE_LOG(CONTRACTOR_CODE) references CONTRACTORS(CONTRACTOR_CODE),
		GATE_TO_DAY as GATE_LOG(ENTRY_DATE) references DAILY_REPORTS(REPORT_DATE),
		GATE_TO_EQUIPMENT as GATE_LOG(SUBJECT_ID) references EQUIPMENT(EQUIPMENT_ID),
		GATE_TO_WORKER as GATE_LOG(SUBJECT_ID) references WORKERS(WORKER_ID),
		EQLOG_TO_CONTRACTOR as EQUIPMENT_LOG(CONTRACTOR_CODE) references CONTRACTORS(CONTRACTOR_CODE),
		EQLOG_TO_DAY as EQUIPMENT_LOG(LOG_DATE) references DAILY_REPORTS(REPORT_DATE),
		EQLOG_TO_EQUIPMENT as EQUIPMENT_LOG(EQUIPMENT_ID) references EQUIPMENT(EQUIPMENT_ID),
		TS_TO_CONTRACTOR as TIMESHEETS(CONTRACTOR_CODE) references CONTRACTORS(CONTRACTOR_CODE),
		TS_TO_DAY as TIMESHEETS(WORK_DATE) references DAILY_REPORTS(REPORT_DATE),
		TS_TO_WORKER as TIMESHEETS(WORKER_ID) references WORKERS(WORKER_ID),
		WDH_TO_CONTRACTOR as WORKER_DAY_HOURS(CONTRACTOR_CODE) references CONTRACTORS(CONTRACTOR_CODE),
		WDH_TO_DAY as WORKER_DAY_HOURS(WORK_DATE) references DAILY_REPORTS(REPORT_DATE),
		WDH_TO_WORKER as WORKER_DAY_HOURS(WORKER_ID) references WORKERS(WORKER_ID),
		INVOICE_TO_CONTRACTOR as INVOICES(CONTRACTOR_CODE) references CONTRACTORS(CONTRACTOR_CODE),
		LINE_TO_INVOICE as INVOICE_LINES(INVOICE_NO) references INVOICES(INVOICE_NO),
		LINEDAY_TO_DAY as INVOICE_LINE_DAYS(LINE_DAY) references DAILY_REPORTS(REPORT_DATE),
		LINEDAY_TO_LINE as INVOICE_LINE_DAYS(INVOICE_NO,LINE_NO) references INVOICE_LINES(INVOICE_NO,LINE_NO),
		TICKET_TO_CONTRACTOR as TICKETS(CONTRACTOR_CODE) references CONTRACTORS(CONTRACTOR_CODE),
		ITEM_TO_EQUIPMENT as TICKET_ITEMS(ITEM_ID) references EQUIPMENT(EQUIPMENT_ID),
		ITEM_TO_TICKET as TICKET_ITEMS(TICKET_NO) references TICKETS(TICKET_NO),
		EXCEPTION_TO_INVOICE as EXCEPTIONS(INVOICE_NO) references INVOICES(INVOICE_NO),
		DECISION_TO_EXCEPTION as DECISIONS(EXCEPTION_ID) references EXCEPTIONS(EXCEPTION_ID),
		UIFLAG_TO_CONTRACT as UI_FLAGS(CONTRACT_ID) references CONTRACTS(CONTRACT_ID),
		UIFLAG_TO_KPIS as UI_FLAGS(CONTRACT_ID) references UI_KPIS(CONTRACT_ID),
		UIKPIS_TO_CONTRACT as UI_KPIS(CONTRACT_ID) references CONTRACTS(CONTRACT_ID)
	)
	facts (
		RATES.RATE_PHP as rate_php with synonyms=('day rate','hourly rate','contract rate') comment='Contract rate in PHP per unit.',
		RATES.STANDBY_RATE_PHP as standby_rate_php with synonyms=('idle rate','standby rate') comment='Rate in PHP per day for equipment on standby/idle.',
		DAILY_REPORTS.CAMP_HEADCOUNT as camp_headcount with synonyms=('camp population','people in camp','headcount') comment='Number of people in camp that day (one value per day; do not sum across days unless asked for a total).',
		GATE_LOG.GATE_HOURS as DATEDIFF('minute', time_in, time_out) / 60 with synonyms=('on-site hours','hours on site','time on site') comment='Hours between time in and time out for this entry.',
		EQUIPMENT_LOG.HOURS_RUN as hours_run with synonyms=('run hours','operating hours'),
		TIMESHEETS.TIMESHEET_HOURS as hours with synonyms=('hours worked','billed hours'),
		WORKER_DAY_HOURS.DAY_GATE_HOURS as gate_hours with synonyms=('on-site hours','gate hours'),
		WORKER_DAY_HOURS.DAY_TIMESHEET_HOURS as timesheet_hours,
		WORKER_DAY_HOURS.HOURS_OVER_GATE as hours_over_gate with synonyms=('excess hours','unsupported hours'),
		INVOICES.SUBTOTAL_PHP as subtotal,
		INVOICES.VAT_PHP as vat,
		INVOICES.TOTAL_PHP as total,
		INVOICE_LINES.QTY as qty,
		INVOICE_LINES.UNIT_RATE as unit_rate,
		INVOICE_LINES.LINE_AMOUNT_PHP as amount,
		TICKET_ITEMS.ITEM_QTY as qty,
		TICKET_ITEMS.ITEM_HOURS as hours,
		EXCEPTIONS.FLAGGED_PHP as flagged_php,
		DECISIONS.UPHELD_PHP as upheld_php,
		DECISIONS.OVERBILLED_PHP as overbilled_php,
		DECISIONS.WITHHELD_PHP as withheld_php,
		DECISIONS.ALLOWED_PHP as allowed_php,
		ACTIVITY.AMOUNT_EFFECT as amount_effect comment='Decisions and overrides: amount not payable (overbilled + withheld). Approvals: amount to pay before VAT.',
		UI_FLAGS.FLAG_IMPACT_PHP as impact_php with synonyms=('upheld','not payable','overbilled') comment='Upheld (not payable) amount of the finding.',
		UI_FLAGS.FLAG_FLAGGED_PHP as billed_value comment='Amount the check flagged.',
		UI_FLAGS.FLAG_CREDIT_PHP as credit_php comment='Credit note amount recorded (RECOVERED findings).',
		UI_KPIS.KPI_INVOICES as invoices,
		UI_KPIS.KPI_INVOICES_APPROVED as invoices_approved,
		UI_KPIS.KPI_INVOICES_WAITING as invoices_waiting,
		UI_KPIS.KPI_INVOICES_WITH_FINDINGS as invoices_with_findings,
		UI_KPIS.KPI_DOCS_REVIEWED as docs_reviewed,
		UI_KPIS.KPI_SPEND_REVIEWED as spend_reviewed comment='Invoice total due incl. VAT, PHP.',
		UI_KPIS.KPI_FINDINGS as findings,
		UI_KPIS.KPI_OPEN_FLAGS as open_flags,
		UI_KPIS.KPI_CONFIRMED_FLAGS as confirmed_flags,
		UI_KPIS.KPI_DISMISSED_FLAGS as dismissed_flags,
		UI_KPIS.KPI_RECOVERED_FLAGS as recovered_flags,
		UI_KPIS.KPI_UPHELD_PHP as upheld_php comment='Not-payable amount of all current decisions, PHP.',
		UI_KPIS.KPI_POTENTIAL_PHP as potential_issues comment='Upheld amount of OPEN findings, PHP.',
		UI_KPIS.KPI_CONFIRMED_PHP as confirmed_issues comment='Upheld amount of CONFIRMED and RECOVERED findings, PHP.',
		UI_KPIS.KPI_RECOVERED_PHP as recovered comment='Credit notes recorded, PHP.'
	)
	dimensions (
		CONTRACTORS.CONTRACTOR_CODE as contractor_code comment='Short contractor code used in all site records.',
		CONTRACTORS.CONTRACTOR_NAME as contractor_name with synonyms=('contractor','vendor name','company') comment='Contractor company name, e.g. PumpCo Services Inc., AquaHaul Trucking. Match with ILIKE on the brand word.' is_enum,
		CONTRACTORS.CONTRACT_ID as contract_id comment='Service contract the contractor is under.',
		CONTRACTORS.SCOPE as scope comment='Scope of services.',
		CONTRACTORS.BASE as base comment='Contractor base location.',
		CONTRACTORS.TERM_START as term_start with synonyms=('contract start') comment='First day of the contractor''s contract term.',
		CONTRACTORS.TERM_END as term_end with synonyms=('contract end','term expiry') comment='Last day of the contractor''s contract term; work after it is outside the term.',
		CONTRACTS.CONTRACT_ID as contract_id with synonyms=('agreement number','MSA'),
		CONTRACTS.CONTRACT_TITLE as title,
		CONTRACTS.OPERATOR as operator,
		CONTRACTS.SITE_ID as site_id,
		CONTRACTS.CONTRACT_STATUS as status comment='EXTRACTED or CONFIRMED.',
		CONTRACTS.EFFECTIVE_DATE as effective_date,
		RATES.CONTRACT_ID as contract_id,
		RATES.CONTRACTOR_CODE as contractor_code,
		RATES.RATE_CODE as rate_code,
		RATES.RATE_ITEM as item with synonyms=('rate description','role rate','equipment rate'),
		RATES.RATE_UNIT as unit,
		RATES.IS_EQUIPMENT as is_equipment,
		RULE_PARAMS.CONTRACT_ID as contract_id,
		RULE_PARAMS.PARAM as param,
		RULE_PARAMS.PARAM_VALUE as value::STRING,
		RULE_PARAMS.SOURCE_CLAUSE as source_clause,
		CLAUSES.CONTRACT_ID as contract_id,
		CLAUSES.CLAUSE_NO as clause_no,
		CLAUSES.CLAUSE_TITLE as title,
		CLAUSES.ARTICLE as article,
		CLAUSES.CLAUSE_TEXT as clause_text,
		DAILY_REPORTS.WEATHER as weather with synonyms=('weather conditions') comment='e.g. Fair, Heavy rain, Typhoon signal no. 2' is_enum,
		DAILY_REPORTS.OPS_STATUS as ops_status with synonyms=('operations status','suspension','weather suspension','typhoon suspension','stand-down') comment='NORMAL or SUSPENDED. SUSPENDED means site operations were suspended (typically weather/typhoon).' is_enum,
		DAILY_REPORTS.ACTIVITIES as activities,
		DAILY_REPORTS.SUPERVISOR_NOTES as supervisor_notes,
		DAILY_REPORTS.REPORTED_BY as reported_by,
		DAILY_REPORTS.REPORT_DATE as report_date with synonyms=('site date','day'),
		GATE_LOG.GATE_ENTRY_ID as gate_entry_id,
		GATE_LOG.SUBJECT_TYPE as subject_type comment='PERSON (personnel, crew, workers) or EQUIPMENT (vehicles, trucks, units).' is_enum,
		GATE_LOG.SUBJECT_ID as subject_id comment='Worker ID for a PERSON',
		GATE_LOG.SUBJECT_NAME as subject_name comment='Person name or equipment description (e.g. Water truck).',
		GATE_LOG.CONTRACTOR_CODE as contractor_code,
		GATE_LOG.GATE as gate comment='MAIN or SECONDARY gate.' is_enum,
		GATE_LOG.GATE_REMARKS as remarks,
		GATE_LOG.ENTRY_DATE as entry_date with synonyms=('gate date'),
		GATE_LOG.TIME_IN as time_in,
		GATE_LOG.TIME_OUT as time_out,
		EQUIPMENT_LOG.EQUIPMENT_ID as equipment_id with synonyms=('unit','equipment','pump','crane'),
		EQUIPMENT_LOG.CONTRACTOR_CODE as contractor_code,
		EQUIPMENT_LOG.EQUIPMENT_STATUS as status with synonyms=('status','operated','idle','standby') comment='OPERATING (operated/worked), IDLE (standby, on location but not working), OFF_HIRE, DEMOBILIZED.' is_enum,
		EQUIPMENT_LOG.EQUIPMENT_REMARKS as remarks,
		EQUIPMENT_LOG.LOG_DATE as log_date,
		TIMESHEETS.WORKER_ID as worker_id,
		TIMESHEETS.WORKER_NAME as worker_name with synonyms=('personnel name','crew member','employee'),
		TIMESHEETS.CONTRACTOR_CODE as contractor_code,
		TIMESHEETS.ROLE as role with synonyms=('position','job title','trade') is_enum,
		TIMESHEETS.APPROVED_BY as approved_by,
		TIMESHEETS.WORK_DATE as work_date,
		EQUIPMENT.EQUIPMENT_ID as equipment_id,
		EQUIPMENT.EQUIPMENT_NAME as equipment_name with synonyms=('equipment type','vehicle'),
		EQUIPMENT.EQUIPMENT_CONTRACTOR_CODE as contractor_code,
		WORKERS.WORKER_ID as worker_id,
		WORKERS.WORKER_NAME as worker_name,
		WORKERS.WORKER_CONTRACTOR_CODE as contractor_code,
		WORKERS.WORKER_ROLE as role,
		WORKER_DAY_HOURS.WORKER_ID as worker_id,
		WORKER_DAY_HOURS.CONTRACTOR_CODE as contractor_code,
		WORKER_DAY_HOURS.ROLE as role,
		WORKER_DAY_HOURS.GATES as gates,
		WORKER_DAY_HOURS.WORK_DATE as work_date,
		INVOICES.INVOICE_NO as invoice_no,
		INVOICES.CONTRACT_ID as contract_id,
		INVOICES.CONTRACTOR_CODE as contractor_code,
		INVOICES.INVOICE_DATE as invoice_date,
		INVOICES.PERIOD_START as period_start with synonyms=('service week','service period'),
		INVOICES.PERIOD_END as period_end,
		INVOICE_LINES.INVOICE_NO as invoice_no,
		INVOICE_LINES.LINE_NO as line_no,
		INVOICE_LINES.LINE_DESCRIPTION as description,
		INVOICE_LINES.RATE_CODE as rate_code,
		INVOICE_LINES.LINE_UNIT as unit,
		INVOICE_LINES.TICKET_REFS as ARRAY_TO_STRING(ticket_refs, ', '),
		INVOICE_LINES.SERVICE_DATE as service_date,
		INVOICE_LINE_DAYS.INVOICE_NO as invoice_no,
		INVOICE_LINE_DAYS.LINE_NO as line_no,
		INVOICE_LINE_DAYS.DAY_SOURCE as source,
		INVOICE_LINE_DAYS.LINE_DAY as service_date,
		TICKETS.TICKET_NO as ticket_no,
		TICKETS.CONTRACT_ID as contract_id,
		TICKETS.CONTRACTOR_CODE as contractor_code,
		TICKETS.SIGNED_BY_CONTRACTOR as signed_by_contractor,
		TICKETS.SIGNED_BY_COMPANY_REP as signed_by_company_rep with synonyms=('signed','company signature'),
		TICKETS.COMPANY_REP_NAME as company_rep_name,
		TICKETS.HANDWRITTEN as handwritten,
		TICKETS.TICKET_REMARKS as remarks,
		TICKETS.TICKET_DATE as ticket_date,
		TICKETS.TICKET_PERIOD_START as period_start,
		TICKET_ITEMS.TICKET_NO as ticket_no,
		TICKET_ITEMS.ITEM_TYPE as item_type,
		TICKET_ITEMS.ITEM_ID as item_id comment='Worker ID or equipment ID.',
		TICKET_ITEMS.ITEM_DESCRIPTION as description,
		TICKET_ITEMS.ITEM_ROLE as role,
		TICKET_ITEMS.ITEM_DATE as item_date,
		EXCEPTIONS.EXCEPTION_ID as exception_id,
		EXCEPTIONS.CONTRACT_ID as contract_id,
		EXCEPTIONS.INVOICE_NO as invoice_no,
		EXCEPTIONS.LINE_NO as line_no,
		EXCEPTIONS.CONTRACTOR_CODE as contractor_code,
		EXCEPTIONS.RULE_TYPE as rule_type with synonyms=('check','rule','error type') is_enum,
		EXCEPTIONS.EXCEPTION_SUMMARY as summary,
		EXCEPTIONS.CLAUSE_REFS as clause_refs,
		EXCEPTIONS.EVIDENCE_SUMMARY as evidence_summary with synonyms=('evidence','why flagged'),
		EXCEPTIONS.EXCEPTION_PERIOD_START as period_start,
		DECISIONS.EXCEPTION_ID as exception_id,
		DECISIONS.DECISION_VERSION as version,
		DECISIONS.DECISION as decision with synonyms=('outcome','verdict') sample_values ('CONFIRM', 'CORRECT', 'WITHHOLD', 'DISMISS') is_enum,
		DECISIONS.IS_CURRENT as is_current with synonyms=('current decision','latest decision') comment='TRUE for the latest version of each exception''s decision.',
		DECISIONS.IS_UPHELD as is_upheld with synonyms=('upheld','sustained','flag stands') comment='TRUE when any amount is upheld (overbilled or withheld).',
		DECISIONS.DECISION_CLAUSES as ARRAY_TO_STRING(clauses, ', '),
		DECISIONS.RATIONALE as rationale,
		DECISIONS.DECIDED_BY as decided_by,
		DECISIONS.IS_STALE as is_stale,
		DECISIONS.DECIDED_AT as created_at,
		ACTIVITY.ACTIVITY_CONTRACT_ID as contract_id,
		ACTIVITY.WHO as who with synonyms=('by','user','changed by','approved by','decided by') comment='User name, or MERRY for the agent.',
		ACTIVITY.KIND as kind with synonyms=('event type','action') sample_values ('UPLOAD', 'CONTRACT_CONFIRMED', 'AGENT_DECISION', 'OVERRIDE', 'APPROVAL', 'CONTRACT_EDIT', 'CHAT_ACTION', 'REVIEW', 'CREDIT_NOTE', 'SITE_RECORDS') is_enum,
		ACTIVITY.SUBJECT as subject with synonyms=('invoice','invoice number','what') comment='Invoice number for decisions',
		ACTIVITY.SUMMARY as summary with synonyms=('what happened','details','reason'),
		ACTIVITY.ACTIVITY_AT as at with synonyms=('when','date','time'),
		UI_FLAGS.FLAG_ID as flag_id,
		UI_FLAGS.FLAG_CONTRACT_ID as contract_id,
		UI_FLAGS.FLAG_STATUS as status with synonyms=('review status','finding status','issue status') sample_values ('OPEN', 'CONFIRMED', 'DISMISSED', 'RECOVERED') is_enum,
		UI_FLAGS.FLAG_RULE as rule with synonyms=('issue type','check'),
		UI_FLAGS.FLAG_CONTRACTOR_CODE as contractor_code,
		UI_FLAGS.FLAG_INVOICE_NO as source_doc with synonyms=('invoice','invoice number'),
		UI_FLAGS.FLAG_INVOICE_STATUS as invoice_status comment='Status of the invoice letter: DRAFT or APPROVED.',
		UI_FLAGS.FLAG_DECIDED_BY as decided_by with synonyms=('who decided','decided by','overridden by') comment='MERRY when the current decision is MERRY''s own; otherwise the analyst who overrode it.',
		UI_FLAGS.FLAG_DECIDED_AT as decided_at comment='When the current decision was made.',
		UI_FLAGS.FLAG_OVERRIDE_REASON as override_reason with synonyms=('reason','why it was changed') comment='The analyst''s reason when the current decision is an override; empty for MERRY''s own decisions.',
		UI_FLAGS.FLAG_RATIONALE as rationale comment='MERRY''s reasoning (or the override note) for the current decision.',
		UI_FLAGS.FLAG_DECISION_WORD as decision_word comment='Plain status word of the current decision.',
		UI_FLAGS.FLAG_REVIEW_NOTE as review_note comment='Latest note saved with a review in the Issues tab.',
		UI_KPIS.KPI_CONTRACT_ID as contract_id
	)
	metrics (
		GATE_LOG.GATE_ENTRIES as COUNT(gate_entry_id) with synonyms=('trips','entries','visits','number of trips') comment='Number of gate entries (trips).',
		GATE_LOG.TOTAL_PERSON_HOURS as SUM(gate_hours) with synonyms=('man-hours','person-hours','total gate hours') comment='Sum of on-site hours across all entries/people. Use only when person-hours or man-hours are asked for.',
		GATE_LOG.CREW_ON_SITE_HOURS as DATEDIFF('minute', MIN(time_in), MAX(time_out)) / 60 with synonyms=('hours on site','on-site hours','how long on site','time on site') comment='On-site window of a group (e.g. a contractor''s crew on a day): first time in to last time out. Use for ''how many hours were <contractor> personnel on site''.',
		EQUIPMENT_LOG.TOTAL_HOURS_RUN as SUM(hours_run),
		EQUIPMENT_LOG.OPERATING_DAYS as COUNT_IF(status = 'OPERATING'),
		TIMESHEETS.TOTAL_TIMESHEET_HOURS as SUM(timesheet_hours),
		INVOICES.INVOICED_SUBTOTAL_PHP as SUM(subtotal_php),
		INVOICES.INVOICE_COUNT as COUNT(invoice_no),
		INVOICE_LINES.BILLED_PHP as SUM(line_amount_php),
		TICKETS.TICKET_COUNT as COUNT(ticket_no),
		EXCEPTIONS.TOTAL_FLAGGED_PHP as SUM(flagged_php),
		EXCEPTIONS.EXCEPTION_COUNT as COUNT(exception_id),
		DECISIONS.TOTAL_UPHELD_PHP as SUM(upheld_php),
		DECISIONS.TOTAL_OVERBILLED_PHP as SUM(overbilled_php),
		DECISIONS.DECISION_COUNT as COUNT(exception_id),
		ACTIVITY.ACTIVITY_COUNT as COUNT(kind),
		UI_FLAGS.FINDING_COUNT as COUNT(flag_id) with synonyms=('number of findings','number of issues'),
		UI_FLAGS.TOTAL_IMPACT_PHP as SUM(impact_php) with synonyms=('total upheld','total not payable')
	)
	comment='MERRY site audit model for the sites of the onboarded service contracts. Site records (gate log, equipment log, timesheets, daily reports), contract terms (contractors, rates, rule parameters, clauses), curated invoices and field tickets, rule-check exceptions and agent decisions. Amounts are PHP. Service weeks run Monday to Sunday.'
	ai_sql_generation 'Filter contractors by name with ILIKE ''%<brand word>%'' on contractor_name (join via contractor_code). "Personnel", "crew", "workers" are gate_log rows with subject_type = ''PERSON''; "trucks", "trips", "units" are subject_type = ''EQUIPMENT''. A trip or entry is one gate_log row. Equipment "operated" means equipment_status = ''OPERATING''; "standby"/"idle" means ''IDLE''. A suspended or typhoon day is a daily_reports row with ops_status = ''SUSPENDED''. "How many hours were <contractor> personnel/crew on site" on a day means crew_on_site_hours (first time in to last time out), not the sum over people; use total_person_hours only for person-hours or man-hours. For "per day" questions return one row per date. Always include the date column and the values asked for. Amounts are PHP.'
	ai_verified_queries (
		EQUIPMENT_STATUS_BY_DAY AS ( 
QUESTION 'What was the status and hours run of a given equipment unit for each day in a date range?' 
ONBOARDING_QUESTION true
SQL 'SELECT log_date, equipment_id, equipment_status, hours_run, equipment_remarks FROM __equipment_log WHERE equipment_id = ''CR-301'' AND log_date BETWEEN ''2026-08-31'' AND ''2026-09-06'' ORDER BY log_date'),
		GATE_VS_TIMESHEET_HOURS AS ( 
QUESTION 'For a given contractor and date range, compare gate (on-site) hours with timesheet hours per worker per day.' 
ONBOARDING_QUESTION true
SQL 'SELECT h.work_date, h.worker_id, w.worker_name, h.role, h.gates, h.day_gate_hours, h.day_timesheet_hours, h.hours_over_gate FROM __worker_day_hours h JOIN __workers w ON w.worker_id = h.worker_id JOIN __contractors c ON c.contractor_code = h.contractor_code WHERE c.contractor_name ILIKE ''%Liftmax%'' AND h.work_date BETWEEN ''2026-09-14'' AND ''2026-09-20'' ORDER BY h.work_date, h.worker_id'),
		SUSPENDED_DAYS_WITH_WEATHER AS ( 
QUESTION 'Which days were site operations suspended, and what was the weather?' 
ONBOARDING_QUESTION true
SQL 'SELECT report_date, ops_status, weather, supervisor_notes FROM __daily_reports WHERE ops_status = ''SUSPENDED'' ORDER BY report_date'),
		UPHELD_DECISIONS_BY_CONTRACTOR_RULE AS ( 
QUESTION 'What past decisions were upheld, by contractor and rule type, with amounts?' 
ONBOARDING_QUESTION true
SQL 'SELECT c.contractor_name, e.rule_type, COUNT(*) AS decisions,
       COUNT(DISTINCT e.exception_period_start) AS periods,
       SUM(d.upheld_php) AS upheld_php, SUM(d.overbilled_php) AS overbilled_php, SUM(d.withheld_php) AS withheld_php
FROM __decisions d JOIN __exceptions e ON e.exception_id = d.exception_id JOIN __contractors c ON c.contractor_code = e.contractor_code WHERE d.is_current = TRUE AND d.is_upheld = TRUE GROUP BY c.contractor_name, e.rule_type ORDER BY periods DESC, upheld_php DESC'),
		INVOICE_DECISION_HISTORY AS ( 
QUESTION 'What did we decide on <invoice number>, and did anyone change it?' 
ONBOARDING_QUESTION false
SQL 'SELECT activity_at, who, kind, summary, amount_effect FROM __activity WHERE subject = ''<invoice number>'' AND kind IN (''AGENT_DECISION'', ''OVERRIDE'', ''APPROVAL'') ORDER BY activity_at')
	)
	with extension (CA='{"tables":[{"name":"contractors","dimensions":[{"name":"contractor_code","unique":true},{"name":"contractor_name"},{"name":"contract_id"},{"name":"scope"},{"name":"base"}],"time_dimensions":[{"name":"term_start"},{"name":"term_end"}]},{"name":"contracts","dimensions":[{"name":"contract_id"},{"name":"contract_title"},{"name":"operator"},{"name":"site_id"},{"name":"contract_status"}],"time_dimensions":[{"name":"effective_date"}]},{"name":"rates","dimensions":[{"name":"contract_id"},{"name":"contractor_code"},{"name":"rate_code"},{"name":"rate_item"},{"name":"rate_unit"},{"name":"is_equipment"}],"facts":[{"name":"rate_php"},{"name":"standby_rate_php"}]},{"name":"rule_params","dimensions":[{"name":"contract_id"},{"name":"param"},{"name":"param_value"},{"name":"source_clause"}]},{"name":"clauses","dimensions":[{"name":"contract_id"},{"name":"clause_no"},{"name":"clause_title"},{"name":"article"},{"name":"clause_text"}]},{"name":"daily_reports","dimensions":[{"name":"weather"},{"name":"ops_status"},{"name":"activities"},{"name":"supervisor_notes"},{"name":"reported_by"}],"facts":[{"name":"camp_headcount"}],"time_dimensions":[{"name":"report_date"}]},{"name":"gate_log","dimensions":[{"name":"gate_entry_id"},{"name":"subject_type"},{"name":"subject_id","equipment ID for EQUIPMENT.":null},{"name":"subject_name"},{"name":"contractor_code"},{"name":"gate"},{"name":"gate_remarks"}],"facts":[{"name":"gate_hours"}],"metrics":[{"name":"gate_entries"},{"name":"total_person_hours"},{"name":"crew_on_site_hours"}],"time_dimensions":[{"name":"entry_date"},{"name":"time_in"},{"name":"time_out"}]},{"name":"equipment_log","dimensions":[{"name":"equipment_id"},{"name":"contractor_code"},{"name":"equipment_status"},{"name":"equipment_remarks"}],"facts":[{"name":"hours_run"}],"metrics":[{"name":"total_hours_run"},{"name":"operating_days"}],"time_dimensions":[{"name":"log_date"}]},{"name":"timesheets","dimensions":[{"name":"worker_id"},{"name":"worker_name"},{"name":"cont